// Package web exposes the generated frontend bundle embedded into the video-rename binary.
package web

import (
	"embed"
	"io/fs"
)

// files includes the frontend distribution generated by `npm --prefix web run build`.
//
//go:embed all:dist
var files embed.FS

// Files returns the frontend distribution rooted at dist.
func Files() (fs.FS, error) {
	return fs.Sub(files, "dist")
}
